mapper.select:
select si.create_time as billDate, si.id as soId, si.code as soCode, si.approve_status as soApproveStatus, sd.id as soDetailId, sd.qty as soQty, sdn.id as deliveryNoticeId, sdn.code as deliveryNoticeCode, sdn.approve_status as deliveryNoticeApproveStatus, sdnd.id as deliveryNoticeDetailId, sdnd.delivery_qty as deliveryQty, sd.sku_id as skuId, si.warehouse_id as warehouseId, si.virtual_warehouse_id as virtualWarehouseId, COALESCE(COALESCE(sd.frozen_time,sdn.create_time),sd.create_time) as frozenTime, case when sdn.id is null then sd.frozen_qty else COALESCE(sdnd.last_picking_qty,0) end as frozenQty, '' as outstockOrderId, '' as outstockOrderStatus, 0 as outstockQty, '' as outstockOrderCode, null as outstockOrderTime, '' as outstockOrderType, true as isOutstock from so_info si inner join so_detail sd on si.id = sd.main_id and sd.is_deleted = false left join so_delivery_notice_detail sdnd on sd.id = sdnd.source_detail_id and sdnd.is_deleted = false left join so_delivery_notice sdn on sdn.id = sdnd.main_id and sdn.is_deleted = false and sdn.invalid_status = false where si.is_deleted = false and si.invalid_status = false and si.virtual_warehouse_id != ''
and si.create_time >= #{startDate}
union all (WITH deliveryNoticeDetail as ( select sdnd.source_detail_id, sum(sdnd.delivery_qty) as totalDeliveryQty from so_delivery_notice sdn inner join so_delivery_notice_detail sdnd on sdn.id = sdnd.main_id and sdnd.is_deleted = false where sdn.invalid_status = false group by sdnd.source_detail_id ) select si.create_time as billDate, si.id as soId, si.code as soCode, si.approve_status as soApproveStatus, sd.id as soDetailId, sd.qty as soQty, '' as deliveryNoticeId, '' as deliveryNoticeCode, '' as deliveryNoticeApproveStatus, '' as deliveryNoticeDetailId, 0 as deliveryQty, sd.sku_id as skuId, si.warehouse_id as warehouseId, si.virtual_warehouse_id as virtualWarehouseId, COALESCE(sd.frozen_time,sd.create_time) as frozenTime, sd.frozen_qty as frozenQty, '' as outstockOrderId, '' as outstockOrderStatus, 0 as outstockQty, '' as outstockOrderCode, null as outstockOrderTime, '' as outstockOrderType, false as isOutstock from so_info si inner join so_detail sd on si.id = sd.main_id and sd.is_deleted = false inner join deliveryNoticeDetail dnd on sd.id = dnd.source_detail_id where si.is_deleted = false and si.invalid_status = false and sd.qty > dnd.totalDeliveryQty and si.virtual_warehouse_id != ''
and si.create_time >= #{startDate}
)

WITH qtyStatistics as ( SELECT sku_id, -- 统计每个区间的数量合计 SUM(CASE WHEN days_diff BETWEEN 0 AND 10 THEN frozen_qty ELSE 0 END) AS tenDaysCount, SUM(CASE WHEN days_diff BETWEEN 11 AND 20 THEN frozen_qty ELSE 0 END) AS twentyDaysCount, SUM(CASE WHEN days_diff BETWEEN 21 AND 30 THEN frozen_qty ELSE 0 END) AS thirtyDaysCount, SUM(CASE WHEN days_diff BETWEEN 31 AND 60 THEN frozen_qty ELSE 0 END) AS sixtyDaysCount, SUM(CASE WHEN days_diff BETWEEN 61 AND 90 THEN frozen_qty ELSE 0 END) AS ninetyDaysCount, SUM(CASE WHEN days_diff > 90 THEN frozen_qty ELSE 0 END) AS aboveNinetyDaysCount, SUM(frozen_qty) AS totalFrozenQty FROM ( SELECT sku_id, frozen_qty, DATE_PART('day', COALESCE(outstock_order_time, NOW()) - frozen_time) + 1 AS days_diff FROM so_b2b_processing WHERE frozen_time IS NOT NULL ) AS subquery GROUP BY sku_id ) select 'b2b' as type, qs.sku_id as skuId, pd.sku_no as skuNo, pd.name as productName, qs.totalFrozenQty, qs.tenDaysCount, qs.twentyDaysCount, qs.thirtyDaysCount, qs.sixtyDaysCount, qs.ninetyDaysCount, qs.aboveNinetyDaysCount from qtyStatistics qs left join product_detail pd on qs.sku_id = pd.id and pd.is_deleted = false
${params.sqlMap.default} and qs.totalFrozenQty > 0
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
qs.totalFrozenQty desc
